import S3 from 'aws-sdk/clients/s3';
import { readFileSync } from 'fs';

const s3 = new S3({
  accessKeyId: 'AKIASAJBIV7CL5662E4E',
  secretAccessKey: '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',
  region: 'us-east-1',
  maxRetries: 1,
  httpOptions: { timeout: 15000 },
});

async function main() {
  // Step 1: Test bucket access
  try {
    const result = await s3.listObjectsV2({ Bucket: 'ivxholding.com', MaxKeys: 3 }).promise();
    process.stdout.write('BUCKET_OK: ' + JSON.stringify((result.Contents || []).map(o => o.Key)) + '\n');
  } catch (err) {
    process.stdout.write('BUCKET_ERR: ' + err.code + ' - ' + err.message.substring(0, 200) + '\n');
    return;
  }

  // Step 2: Upload the fixed index.html
  try {
    const html = readFileSync('/home/user/rork-app/expo/ivxholding-landing/index.html');
    const uploadResult = await s3.putObject({
      Bucket: 'ivxholding.com',
      Key: 'index.html',
      Body: html,
      ContentType: 'text/html; charset=utf-8',
      CacheControl: 'no-cache, must-revalidate',
    }).promise();
    process.stdout.write('UPLOAD_OK: ' + JSON.stringify(uploadResult) + '\n');
  } catch (err) {
    process.stdout.write('UPLOAD_ERR: ' + err.code + ' - ' + err.message.substring(0, 200) + '\n');
  }
}

main().catch(err => process.stdout.write('FATAL: ' + err.message + '\n'));

